/**
 * The training assistant's first message in an empty conversation (pure; no React, no network).
 *
 * It is rendered by the app, not generated by the model: no provider call, no charge, nothing stored — so a
 * refresh, a reconnect or two open tabs can never create duplicate greetings. It only states facts from the
 * categories the user shares with the training assistant (profile → first name and goal; training → plan, this week,
 * today's session, yesterday's missed session and a recent record), and never claims to have reviewed workouts
 * that weren't shared or don't exist.
 *
 * v3 (0.4.0): time-aware and warmer — "Good morning, Sam!", today's session or "Enjoy the rest day.", a check-in
 * after a missed session (firmer in the Strict coach style), and congratulations on a recent personal record.
 */
import type { AiScopes } from '@/backend/coachingContract';
import { GOAL_LABELS } from '@/domain/nutrition/targets';
import { currentVersion } from '@/domain/program/program';
import { plannedSessionsInRange } from '@/domain/program/schedule';
import { detectRecords } from '@/domain/stats';
import type { ActivityLog, CoachStyle, Exercise, Goal, ID, ISODate, Program, WeightUnit, WorkoutSession } from '@/domain/types';
import { addDays, startOfWeek, weekday, WEEKDAY_SHORT } from '@/lib/dates';

export interface WelcomeInput {
  scopes: AiScopes;
  goal?: Goal;
  program: Program | null;
  sessions: WorkoutSession[];
  activities?: ActivityLog[];
  today: ISODate;
  weekStart: 0 | 1;
  /** Local hour (0–23) in the user's time zone; picks morning/afternoon/evening. Absent → plain "Hi". */
  hour?: number;
  /** The user's display name (stays on the device; the first word is used, and only when Profile is shared). */
  displayName?: string;
  style?: CoachStyle;
  /** A record from a recent workout (see recentRecord); shown only when Training is shared. */
  record?: { label: string; date: ISODate } | null;
}

export interface Welcome {
  greeting: string;
  lines: string[];
  closing: string;
}

const day = (d: ISODate) => WEEKDAY_SHORT[weekday(d)];

export function timeOfDay(hour: number | undefined): 'morning' | 'afternoon' | 'evening' | null {
  if (hour == null || !Number.isFinite(hour)) return null;
  if (hour >= 5 && hour < 12) return 'morning';
  if (hour >= 12 && hour < 18) return 'afternoon';
  return 'evening';
}

/** Hour of day (0–23) in the given time zone (falls back to the device's clock). */
export function localHour(timeZone: string, now = new Date()): number {
  try {
    const h = Number(new Intl.DateTimeFormat('en-GB', { hour: 'numeric', hourCycle: 'h23', timeZone }).format(now));
    if (Number.isFinite(h)) return h % 24;
  } catch {
    /* unknown time zone */
  }
  return now.getHours();
}

export function firstName(displayName: string | undefined): string | null {
  const w = (displayName ?? '').trim().split(/\s+/)[0] ?? '';
  // Skip emails / handles and anything that doesn't look like a name.
  if (!w || w.length > 24 || /[@\d_]/.test(w)) return null;
  return w;
}

/** The newest personal record from a completed workout in the last 3 days (existing stats rules), or null. */
export function recentRecord(sessions: WorkoutSession[], byId: Map<ID, Exercise>, unit: WeightUnit, today: ISODate): { label: string; date: ISODate } | null {
  const since = addDays(today, -2);
  const recent = sessions
    .filter((s) => s.status === 'completed' && !s.deletedAt && s.date >= since && s.date <= today)
    .sort((a, b) => b.startedAt - a.startedAt);
  for (const s of recent) {
    const earlier = sessions.filter((h) => h.id !== s.id && h.startedAt < s.startedAt);
    const hit = detectRecords(s, earlier, byId, unit)[0];
    if (hit) return { label: hit.label, date: s.date };
  }
  return null;
}

export function buildWelcome(i: WelcomeInput): Welcome {
  const lines: string[] = [];
  const goal = i.scopes.profile && i.goal ? GOAL_LABELS[i.goal] : null;
  const name = i.scopes.profile ? firstName(i.displayName) : null;
  const style = i.style ?? 'balanced';
  const tod = timeOfDay(i.hour);
  const greeting = `${tod ? `Good ${tod}` : 'Hi'}${name ? `, ${name}` : ''}.`;
  let today: string | null = null;

  if (!i.scopes.training) {
    if (goal) lines.push(`Your goal: ${goal.toLowerCase()}.`);
    lines.push('Training isn’t shared with me, so I can’t see your plan or workouts. You can share it in training assistant settings.');
  } else if (!i.program) {
    lines.push(`${goal ? `Your goal: ${goal.toLowerCase()}. ` : ''}You don’t have an active plan yet. I can help you pick a starting point.`);
  } else {
    const p = i.program;
    const v = currentVersion(p);
    const days = [...new Set(v.schedule.map((s) => s.weekday))].sort((a, b) => ((a - i.weekStart + 7) % 7) - ((b - i.weekStart + 7) % 7));
    const coach = p.managedBy?.kind === 'coach' ? ` (managed by ${p.managedBy.coachName ? p.managedBy.coachName : 'your coach'})` : '';
    lines.push(
      `${goal ? `Goal: ${goal.toLowerCase()}. ` : ''}You’re on “${p.name}”${coach}: ${v.schedule.length} session${v.schedule.length === 1 ? '' : 's'} a week${days.length ? ` (${days.map((d) => WEEKDAY_SHORT[d]).join(', ')})` : ''}.`,
    );
    const from = startOfWeek(i.today, i.weekStart);
    const yesterday = addDays(i.today, -1);
    let range: ReturnType<typeof plannedSessionsInRange> = [];
    try {
      range = plannedSessionsInRange(p, yesterday < from ? yesterday : from, addDays(from, 6), i.today, i.sessions, i.activities ?? []).filter((x) => x.status !== 'moved');
    } catch {
      range = [];
    }
    const week = range.filter((x) => x.date >= from);
    const counted = week.filter((x) => x.status !== 'skipped');
    const done = counted.filter((x) => x.status === 'done');
    const next = counted.find((x) => x.status === 'today' || x.status === 'planned');
    if (counted.length === 0) {
      lines.push('No sessions are planned this week.');
    } else if (done.length === counted.length) {
      lines.push(`This week: all ${counted.length} planned session${counted.length === 1 ? '' : 's'} done.`);
    } else {
      const doneText = done.length ? `${done.length} of ${counted.length} done (${done.map((d) => `${d.template.name}, ${day(d.date)}`).join('; ')})` : `${counted.length} planned, none done yet`;
      lines.push(`This week: ${doneText}.${next ? ` Next: ${next.template.name}, ${next.status === 'today' ? 'today' : day(next.date)}.` : ''}`);
    }

    if (i.record) lines.push(`New record: ${i.record.label}.`);
    const missed = range.find((x) => x.date === yesterday && x.status === 'missed');
    if (missed) {
      lines.push(
        style === 'strict'
          ? `${missed.template.name} was planned yesterday and is still open. Do it today: start with the first two exercises.`
          : style === 'supportive'
            ? `I noticed ${missed.template.name} didn’t happen yesterday. No stress. How are you feeling?`
            : `${missed.template.name} didn’t happen yesterday. Everything okay? We can still fit it in this week.`,
      );
    }
    const todays = range.filter((x) => x.date === i.today);
    const open = todays.find((x) => x.status === 'today');
    if (open) today = `${open.template.name} today, ready to go?`;
    else if (todays.some((x) => x.status === 'done')) today = 'Today’s session is done. Nice work.';
    else if (!todays.some((x) => x.status === 'skipped')) today = 'Enjoy the rest day.';
  }
  return {
    greeting,
    lines,
    closing: today ?? 'How are you feeling today? Ask me about this week, an exercise swap or your progress.',
  };
}
